S = "Hakeem Force Academy"
QS = [
(S, "Which is the deepest known point of the Earth's surface?", ["Puerto Rico Trench", "Mariana Trench", "Java Trench", "Tonga Trench"], 1, "The Challenger Deep in the Mariana Trench of the western Pacific is the deepest known point, at about 10,900 to 11,000 metres below sea level.", "Mount Everest, the highest point, would be covered by more than 2 km of water if placed in the Challenger Deep.", [1118]),
(S, "When did the Al-Khalid main battle tank enter service with the Pakistan Army?", ["1998", "2001", "2004", "2008"], 1, "The Al-Khalid (MBT-2000), developed by Pakistan with Chinese help, entered service in 2001.", "Some sources mention 2004 for its formal presentation, and the upgraded Al-Khalid-I was inducted in July 2020.", [4232]),
(S, "What is the definition of a noun?", ["A word that describes an action", "A word that names a person, place, thing or idea", "A word that describes a noun", "A word that joins two sentences"], 1, "A noun is a naming word: it names a person, place, animal, thing or idea.", "A verb shows action, an adjective describes a noun, and a conjunction joins words or clauses.", [3592]),
(S, "A square matrix whose determinant is zero is called what?", ["Singular matrix", "Scalar matrix", "Identity matrix", "Symmetric matrix"], 0, "A square matrix with determinant equal to zero has no inverse and is called a singular matrix.", "A matrix with a non-zero determinant is called non-singular and has an inverse.", [1119, 883]),
(S, "What is a square matrix?", ["A matrix with equal number of rows and columns", "A matrix with only one row", "A matrix with all elements zero", "A matrix with only one column"], 0, "A square matrix has the same number of rows as columns, for example 3 by 3.", "Only square matrices have determinants and can have inverses.", [3593]),
(S, "One degree of angle is equal to how many minutes?", ["100", "30", "60", "360"], 2, "One degree is divided into 60 minutes, and one minute into 60 seconds.", "A full circle measures 360 degrees.", [354, 1596, 2496, 1526]),
(S, "What is the radian measure of 60 degrees?", ["pi/6", "pi/4", "2pi/3", "pi/3"], 3, "Radians = degrees x pi/180 = 60 x pi/180 = pi/3.", "180 degrees equals pi radians.", [3902]),
(S, "What does the word 'delight' mean?", ["Great pleasure or joy", "Deep sadness", "Sudden anger", "Mild confusion"], 0, "Delight means great pleasure or joy; as a verb it means to please greatly.", "A synonym of delight is joy, and an antonym is sorrow.", [3212, 3757]),
(S, "In which year did Allama Iqbal deliver his famous Allahabad Address (Khutba)?", ["1927", "1930", "1933", "1940"], 1, "Allama Iqbal gave his presidential address at the Muslim League session in Allahabad in December 1930, proposing a Muslim state in north-west India.", "The Lahore Resolution followed ten years later, in 1940.", [2685]),
(S, "Where did the Holy Prophet (SAW) deliver the Last Sermon (Khutba Hujjat ul Wida)?", ["Cave of Hira", "Mina Mosque in Madinah", "Plain of Arafat", "Masjid-e-Nabawi"], 2, "The Last Sermon was delivered in the valley of Uranah at the plain of Arafat during the Farewell Pilgrimage.", "It was delivered on 9 Dhul Hijjah.", [4319, 642]),
(S, "In which Hijri year was the Last Sermon (Khutba Hujjat ul Wida) delivered?", ["8 AH", "9 AH", "10 AH", "11 AH"], 2, "The Prophet (SAW) performed his only Hajj, the Farewell Pilgrimage, in 10 AH (632 CE).", "He passed away a few months later, in 11 AH.", [4292]),
(S, "What is the antonym of 'demise'?", ["Death", "Birth", "Collapse", "End"], 1, "Demise means death or end, so its opposite is birth or beginning.", "Death, end and collapse are all synonyms of demise.", [176]),
(S, "Which word is a synonym of 'demise'?", ["Birth", "Growth", "Death", "Rise"], 2, "Demise means death or the end of something.", "Its antonym is birth.", [3333]),
(S, "Who was the first woman to head a democratic government in Pakistan, and the first elected woman leader of a Muslim country?", ["Fatima Jinnah", "Benazir Bhutto", "Begum Ra'ana Liaquat Ali Khan", "Nusrat Bhutto"], 1, "Benazir Bhutto became Prime Minister of Pakistan in December 1988, the first woman to head the government of a Muslim-majority country.", "She served twice, 1988 to 1990 and 1993 to 1996.", [1468, 5336]),
(S, "In which body were the Basic Democrats of Ayub Khan's system mainly represented?", ["Electoral college for President and assemblies", "Supreme Court", "Council of Islamic Ideology", "Federal Public Service Commission"], 0, "Basic Democrats, elected from union councils, formed the electoral college that elected the President and members of the assemblies.", "The system was announced in 1959 and used in the 1965 presidential election.", [2534]),
(S, "How many Basic Democrats were there in Ayub Khan's system (40,000 in each wing)?", ["10,000", "20,000", "80,000", "6,000"], 2, "Ayub Khan's Basic Democracies had 80,000 members, 40,000 in East Pakistan and 40,000 in West Pakistan.", "The number was later raised to 120,000, but 80,000 was the original figure.", [3851]),
(S, "What is the derivative of sin x with respect to x?", ["cos x", "minus cos x", "tan x", "minus sin x"], 0, "By the standard rule, d/dx (sin x) = cos x.", "The derivative of cos x is minus sin x.", [409, 1121]),
(S, "What is the derivative of tan x with respect to x?", ["cos squared x", "sec squared x", "cot x", "minus cosec squared x"], 1, "d/dx (tan x) = d/dx (sin x / cos x) = (cos^2 x + sin^2 x) / cos^2 x = sec^2 x.", "The derivative of cot x is minus cosec squared x.", [3597]),
(S, "Pakistan's friendship with which neighbouring country is described as higher than the mountains and deeper than the oceans?", ["India", "Iran", "Afghanistan", "China"], 3, "Pakistani leaders describe the Pakistan-China friendship as higher than the Himalayas and deeper than the oceans.", "The Karakoram Highway and CPEC link the two countries.", [5482]),
(S, "In which province of Pakistan is the Cholistan Desert located?", ["Sindh", "Balochistan", "Punjab", "Khyber Pakhtunkhwa"], 2, "The Cholistan Desert lies in southern Punjab, near Bahawalpur.", "It is locally called Rohi and is an extension of the Thar Desert.", [2654]),
(S, "In which province of Pakistan is the Thar Desert located?", ["Punjab", "Balochistan", "Khyber Pakhtunkhwa", "Sindh"], 3, "The Thar Desert, with Mithi and Umerkot, lies in eastern Sindh and extends into India.", "It is one of the most densely populated deserts in the world.", [946]),
(S, "Which desert is located in Sindh?", ["Thal", "Thar", "Kharan", "Cholistan"], 1, "The Thar Desert, also called the Great Indian Desert, is in the Tharparkar region of Sindh and is the largest desert of Sindh.", "Thar is also home to the largest coal reserves of Pakistan.", [607, 1314, 1129]),
(S, "Which of the following is a desert of Pakistan?", ["Gobi", "Sahara", "Cholistan", "Kalahari"], 2, "Cholistan in Punjab is a desert of Pakistan, along with Thar, Thal and Kharan.", "Gobi is in Asia (Mongolia and China), and Sahara and Kalahari are in Africa.", [3315, 4420]),
(S, "In which province of Pakistan is the Thal Desert located?", ["Sindh", "Punjab", "Balochistan", "Khyber Pakhtunkhwa"], 1, "The Thal Desert lies in Punjab between the Jhelum and Indus rivers, covering districts such as Bhakkar, Layyah and Khushab.", "It is now largely irrigated by the Thal Canal.", [4384]),
(S, "Roughly what fraction of the Earth's land surface is covered by deserts (arid regions)?", ["One tenth", "One third", "One half", "One twentieth"], 1, "Deserts and arid lands cover roughly one third of the Earth's land surface.", "Sources differ depending on how a desert is defined.", [520]),
(S, "Which lake is known as the world's largest permanent desert lake?", ["Lake Victoria", "Lake Turkana", "Lake Baikal", "Lake Superior"], 1, "Lake Turkana in northern Kenya lies in a desert region and is the largest permanent desert lake, nicknamed the Jade Sea.", "It is a very alkaline lake in the Great Rift Valley.", [4637]),
(S, "Who composed the music of the national anthem of Pakistan?", ["Hafeez Jalandhari", "Ahmed G. Chagla", "Allama Iqbal", "Nusrat Fateh Ali Khan"], 1, "The tune of Qaumi Tarana was composed by Ahmed Ghulamali Chagla in 1949.", "Its words were written by Hafeez Jalandhari in 1952.", [5036]),
(S, "What is the determinant of a diagonal matrix?", ["Sum of diagonal elements", "Product of diagonal elements", "Always zero", "Always one"], 1, "For a diagonal matrix all off-diagonal entries are zero, so the determinant is the product of the diagonal elements.", "The sum of diagonal elements is called the trace.", [3598]),
(S, "Who is known as the youngest Microsoft Certified Professional, and from which country did she come?", ["Arfa Karim, Pakistan", "Malala Yousafzai, Pakistan", "Anita Rani, India", "Sana Mir, Pakistan"], 0, "Arfa Karim Randhawa of Faisalabad, Pakistan, became a Microsoft Certified Professional at age 9 in 2004.", "She died in January 2012 at age 16, and a software technology park in Lahore is named after her.", [3838, 4501]),
(S, "In a diagonal matrix, if all the non-zero diagonal elements are equal, what is the matrix called?", ["Identity matrix", "Null matrix", "Scalar matrix", "Symmetric matrix"], 2, "A diagonal matrix with equal diagonal entries is called a scalar matrix.", "A scalar matrix whose diagonal entries are all 1 is the identity matrix.", [900]),
(S, "What is a diagonal matrix?", ["A square matrix whose off-diagonal elements are all zero", "A matrix with all elements equal", "A matrix with one row only", "A matrix whose determinant is always 1"], 0, "A diagonal matrix is a square matrix in which every element outside the main diagonal is zero.", "Scalar and identity matrices are special diagonal matrices.", [3316]),
(S, "If the side of a square is a, what is the length of its diagonal?", ["a", "2a", "a times square root of 2", "a squared"], 2, "By Pythagoras, diagonal = square root of (a^2 + a^2) = a times root 2.", "The diagonals of a square are equal and bisect each other at right angles.", [3599]),
(S, "What is the height of the Diamer Bhasha Dam?", ["172 metres", "272 metres", "372 metres", "212 metres"], 1, "The Diamer Bhasha Dam on the Indus is 272 metres high, per WAPDA.", "It is a roller-compacted concrete dam and one of the tallest of its kind in the world.", [55]),
(S, "What is the diameter of a circle whose radius is 28?", ["14", "28", "56", "84"], 2, "Diameter = 2 x radius = 2 x 28 = 56.", "Circumference equals pi times diameter.", [3600]),
(S, "What is the radius of a circle with diameter 52 cm?", ["13 cm", "26 cm", "104 cm", "52 cm"], 1, "Radius = diameter / 2 = 52 / 2 = 26 cm.", "Area of this circle is pi x 26 x 26.", [3903]),
(S, "Arrange the letters of the word MANAGEMENT in alphabetical order. Which letter is third from the last?", ["M", "G", "N", "T"], 2, "The letters in order are A, A, E, E, G, M, M, N, N, T. From the end: T, N, then N, so the third last is N.", "The word MANAGEMENT has ten letters.", [3995]),
(S, "Which word comes first in the dictionary?", ["Adiabatic", "Addidas", "Adjust", "Adit"], 1, "Compare the third letter: Addidas has d, which comes before i in Adiabatic, Adjust (j) and Adit (i).", "Dictionary order compares letters from left to right.", [4977]),
(S, "At what age did the Holy Prophet Muhammad (SAW) lose his mother, Hazrat Aminah?", ["4 years", "6 years", "8 years", "10 years"], 1, "Hazrat Aminah died at Abwa while returning from Madinah, when the Prophet (SAW) was about 6 years old.", "His grandfather Abdul Muttalib then looked after him until he died when the Prophet was 8.", [752, 1785, 1789, 2306, 2307, 2312, 1213, 4108, 4111, 426]),
(S, "In which year (CE) did the mother of the Holy Prophet (SAW) pass away?", ["570", "577", "580", "590"], 1, "The Prophet (SAW) was born in 570 CE and his mother died when he was about six, around 577 CE.", "The exact year is given slightly differently in some sources.", [958]),
(S, "At what age did Dr. A.Q. Khan, the Pakistani nuclear scientist, die?", ["80", "83", "85", "90"], 2, "Dr. Abdul Qadeer Khan was born on 1 April 1936 and died on 10 October 2021, aged 85.", "He is known as the father of Pakistan's nuclear programme.", [777, 1786]),
(S, "On which date did the singer Lata Mangeshkar die?", ["6 February 2022", "28 September 2021", "6 January 2022", "15 March 2022"], 0, "Lata Mangeshkar, the Indian playback singer, died in Mumbai on 6 February 2022.", "She was born on 28 September 1929.", [2892]),
]
